(function () {
  const template = document.createElement('template');

  template.innerHTML = `
    <slot></slot>
    <span class="content"></span>
    <style>.badge {   display: inline-flex;   position: relative;   transition: background-color 200ms cubic-bezier(0.4, 0, 0.2, 1) 0ms; }  .badge .content {   display: flex;   flex-flow: wrap;   -webkit-box-pack: center;   place-content: center;   -webkit-box-align: center;   align-items: center;   z-index: 1;   color: var(--white);   position: absolute;   top: 0px;   right: 0px;   transition: transform 225ms cubic-bezier(0.4, 0, 0.2, 1) 0ms; }  .badge-is-color-primary {   background-color: var(--primary-main); } .badge-is-color-error {   background-color: var(--error-main); } .badge-is-color-info {   background-color: var(--info-main); } .badge-is-color-warning {   background-color: var(--warning-main); } .badge-is-color-success {   background-color: var(--success-main); }  .badge-is-size-small {   width: 6px;   height: 6px;   transform-origin: 100% 0%;   transform: scale(1) translate(50%, 0);   border-radius: 6px; }  .badge-is-size-large {   transform-origin: 100% 0%;   transform: scale(1) translate(50%, -50%);   height: 20px;   min-width: 20px;   line-height: 1;   padding: 0px 6px;   font-weight: 500;   font-size: 0.75rem;   border-radius: 10px; } </style>
  `;

  class Badge extends HTMLElement {
    #shadow = this.attachShadow({ mode: 'open' });

    /**
     *
     */
    get color() {
      return this.getAttribute('color') || 'primary';
    }

    /**
     *
     */
    get max() {
      const max = this.getAttribute('max');

      if (max) {
        return parseInt(max);
      }

      return 9;
    }

    /**
     *
     */
    get size() {
      return this.getAttribute('size') || 'large';
    }

    /**
     *
     */
    get badgeContent() {
      const badgeContent = this.getAttribute('badgeContent');

      if (badgeContent) {
        return parseInt(badgeContent);
      }

      return 0;
    }

    /**
     *
     */
    static get observedAttributes() {
      return ['color', 'size', 'badgeContent', 'max'];
    }

    /**
     *
     */
    constructor() {
      super();
    }

    /**
     *
     */
    connectedCallback() {
      const wrapper = document.createElement('div');

      wrapper.setAttribute('class', 'badge');
      wrapper.appendChild(template.content.cloneNode(true));

      this.#shadow.appendChild(wrapper);

      this.update();
    }

    /**
     *
     */
    update() {
      const content = this.#shadow.querySelector('.content');

      const classNames = generateClassNames('content', {
        [`badge-is-color-${this.color}`]: true,
        [`badge-is-size-${this.size}`]: true
      });

      content.setAttribute('class', classNames);

      if (this.size == 'large') {
        if (this.badgeContent < this.max) {
          content.innerText = this.badgeContent;
        } else {
          content.innerText = `${this.max}+`;
        }
      }
    }
  }

  customElements.define('punica-badge', Badge);
})();
